+/// Send validated guest spans without borrowing their contents as Rust slices.
+/// Short writes are copied into owned staging before the chain is completed.
+fn send_guest_frame(stream: &UnixStream, slices: &[VolatileSlice<'_>], output: &mut Vec<u8>) {
+    let len: usize = slices.iter().map(VolatileSlice::len).sum();
+    let prefix = (len as u32).to_be_bytes();
+    let mut sent = 0;
+    if output.is_empty() && slices.len() < 1024 {
+        let guards: Vec<_> = slices.iter().map(VolatileSlice::ptr_guard).collect();
+        let mut vectors = Vec::with_capacity(1 + slices.len());
+        vectors.push(libc::iovec {
+            iov_base: prefix.as_ptr().cast_mut().cast(),
+            iov_len: prefix.len(),
+        });
+        vectors.extend(guards.iter().zip(slices).map(|(guard, slice)| libc::iovec {
+            iov_base: guard.as_ptr().cast_mut().cast(),
+            iov_len: slice.len(),
+        }));
+        loop {
+            // SAFETY: the prefix and every validated guest mapping stay live
+            // through the call. No Rust reference aliases guest bytes.
+            let result =
+                unsafe { libc::writev(stream.as_raw_fd(), vectors.as_ptr(), vectors.len() as i32) };
+            if result >= 0 {
+                sent = result as usize;
+                break;
+            }
+            if io::Error::last_os_error().kind() != io::ErrorKind::Interrupted {
+                break;
+            }
+        }
+    }
+    if sent < prefix.len() {
+        output.extend_from_slice(&prefix[sent..]);
+    }
+    let mut skip = sent.saturating_sub(prefix.len());
+    for slice in slices {
+        let offset = skip.min(slice.len());
+        skip -= offset;
+        if offset < slice.len() {
+            let slice = slice.offset(offset).unwrap();
+            let start = output.len();
+            output.resize(start + slice.len(), 0);
+            slice.copy_to(&mut output[start..]);
+        }
+    }
+}
