+fn configure_stream(stream: &UnixStream) -> io::Result<()> {
+    stream.set_nonblocking(true)?;
+    for option in [libc::SO_SNDBUF, libc::SO_RCVBUF] {
+        // SAFETY: stream is live and SOCKET_BUFFER is an initialized integer
+        // option value. The kernel may clamp the request to its configured cap.
+        let result = unsafe {
+            libc::setsockopt(
+                stream.as_raw_fd(),
+                libc::SOL_SOCKET,
+                option,
+                std::ptr::from_ref(&SOCKET_BUFFER).cast(),
+                std::mem::size_of_val(&SOCKET_BUFFER) as libc::socklen_t,
+            )
+        };
+        if result != 0 {
+            return Err(io::Error::last_os_error());
+        }
+    }
+    Ok(())
